patch_result.patch:
--- a/ndpi/src/lib/protocols/softether.c
+++ b/ndpi/src/lib/protocols/softether.c
@@ -201,7 +201,8 @@
   payload += value_siz;
   payload_len -= value_siz;

-  if(strncmp(val1.value.ptr.value_str, "host_name", value_siz) == 0)
+  if(val1.value_size == NDPI_STATICSTRING_LEN("host_name") &&
+     strncmp(val1.value.ptr.value_str, "host_name", NDPI_STATICSTRING_LEN("host_name")) == 0)
     got_hostname = 1;

   for (; tuple_count > 0; --tuple_count) {
@@ -226,8 +227,9 @@
       got_fqdn = 0;
     }

-    if(val2.type == VALUE_DATA && val2.value_size > 0 &&
-       strncmp(val2.value.ptr.value_str, "ddns_fqdn", val2.value_size) == 0)	{
+    if(val2.type == VALUE_DATA &&
+       val2.value_size == NDPI_STATICSTRING_LEN("ddns_fqdn") &&
+       strncmp(val2.value.ptr.value_str, "ddns_fqdn", NDPI_STATICSTRING_LEN("ddns_fqdn")) == 0) {
       got_fqdn = 1;
     }

args:
@@ -201,7 +201,8 @@
