-       strncmp(val2.value.ptr.value_str, "ddns_fqdn", val2.value_size) == 0)	{
+    if(val2.type == VALUE_DATA &&
+       val2.value_size == NDPI_STATICSTRING_LEN("ddns_fqdn") &&
